//! Converts parsed Directives into caller-owned typed configuration.
//!
//! A caller supplies setup functions in Plugin Order and a concrete config type;
//! setup may build an enum generated by plugin.cfg without dynamic Plugin dispatch.
//! Parser tokens are visible only through the temporary setup cursor, never in
//! the returned configuration. One context is shared by every key of a block.

use crate::{Cursor, Error, ServerBlock, ServerBlockKey, Token};

/// A known Directive and its setup function, in Plugin Order.
pub struct Directive<C> {
    pub name: &'static str,
    pub once: bool,
    pub setup: fn(&mut Cursor<'_>, &mut BlockContext<C>) -> Result<(), Error>,
}

/// Typed configuration and listener metadata shared by all keys of one block.
#[derive(Debug)]
pub struct BlockContext<C> {
    keys: Vec<ServerBlockKey>,
    pub config: C,
    /// True when setup has installed a View filter.
    pub view: bool,
    /// Listener addresses, with an empty string denoting all addresses.
    pub listen_addresses: Vec<String>,
}

impl<C> BlockContext<C> {
    /// Normalized keys that share this configuration.
    pub fn keys(&self) -> &[ServerBlockKey] {
        &self.keys
    }
}

/// Run known Directive setup functions in caller-supplied Plugin Order.
pub fn configure<C: Default>(
    blocks: &[ServerBlock],
    registry: &[Directive<C>],
) -> Result<Vec<BlockContext<C>>, Error> {
    let mut configured = Vec::with_capacity(blocks.len());
    for block in blocks {
        for (name, tokens) in &block.directives {
            if !registry.iter().any(|directive| directive.name == name) {
                let token = &tokens[0];
                return Err(Error {
                    file: token.file.clone(),
                    line: token.line,
                    message: format!("Unknown directive '{name}'"),
                });
            }
        }
        let mut context = BlockContext {
            keys: block.normalize_keys()?,
            config: C::default(),
            view: false,
            listen_addresses: vec![String::new()],
        };
        for directive in registry {
            let Some(tokens) = block.directives.get(directive.name) else {
                continue;
            };
            if directive.once
                && let Some(token) = second_occurrence(tokens)
            {
                return Err(Error {
                    file: token.file.clone(),
                    line: token.line,
                    message: format!(
                        "{}: this plugin can only be used once per Server Block",
                        directive.name
                    ),
                });
            }
            let mut cursor = Cursor::new(&tokens[0].file, tokens);
            (directive.setup)(&mut cursor, &mut context)?;
        }
        configured.push(context);
    }
    Ok(configured)
}

fn second_occurrence(tokens: &[Token]) -> Option<&Token> {
    let mut nesting = 0usize;
    for (index, token) in tokens.iter().enumerate() {
        if index > 0 && nesting == 0 {
            let previous = &tokens[index - 1];
            if previous.file != token.file
                || previous.line + previous.text.matches('\n').count() < token.line
            {
                return Some(token);
            }
        }
        match token.text.as_str() {
            "{" => nesting += 1,
            "}" => nesting = nesting.saturating_sub(1),
            _ => {}
        }
    }
    None
}
